const TZ = 'America/New_York';
const i = $('When Executed by Another Workflow').first().json;
const email = String(i.email || '').trim().toLowerCase();
const id = String(i.bookingId || '').trim().toUpperCase();
const digits = (v) => String(v || '').replace(/\D/g, '');
const phone = digits(i.phone);
if (!email && !id && phone.length < 7) return [{ json: { success: false, appointments: [], message: 'Ask for the email, phone number or booking ID used for the booking.' } }];
const after = i.afterTime ? new Date(i.afterTime).getTime() : Date.now() - 3600000;
const before = i.beforeTime ? new Date(i.beforeTime).getTime() : Infinity;
const rows = $input.all().map(r => r.json).filter(r => r['Booking ID']);
const matches = rows.filter(r => {
  const byId = id && String(r['Booking ID']).toUpperCase() === id;
  const byEmail = email && String(r.Email || '').trim().toLowerCase() === email;
  const byPhone = phone.length >= 7 && digits(r.Phone).endsWith(phone.slice(-10));
  if (!(byId || byEmail || byPhone)) return false;
  if (byId) return true;
  const t = new Date(r.Start).getTime();
  return r.Status !== 'Cancelled' && t >= after && t <= before;
});
const appointments = matches.map(r => ({ bookingId: r['Booking ID'], eventId: r['Event ID'], service: r.Service, vehicle: r.Vehicle, start: r.Start, end: r.End, status: r.Status, label: DateTime.fromISO(r.Start, { setZone: true }).setZone(TZ).toFormat("cccc d LLLL 'at' h:mm a") }));
return [{ json: { success: true, count: appointments.length, appointments, message: appointments.length ? appointments.map(a => `${a.service} on ${a.label} (booking ${a.bookingId}, ${a.status})`).join('; ') : 'No upcoming appointments found for those details.' } }];
